const rows = $input.all().map(item => item.json);
const generatedAt = new Date();
const dateFmt = new Intl.DateTimeFormat('pt-BR', {timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'});
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmtDate = value => value ? dateFmt.format(new Date(value)) : '—';
const fmtMoney = value => value === null || value === undefined || value === '' ? '—' : new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value));
const parseProcesses = value => {
  if (typeof value === 'string') { try { value = JSON.parse(value); } catch { return []; } }
  return Array.isArray(value) ? value : [];
};
const uniqueByCpf = new Map();
for (const row of rows) if (!uniqueByCpf.has(String(row['CPF']))) uniqueByCpf.set(String(row['CPF']),row);
const consultations = [...uniqueByCpf.values()];
const distinctCpfCount = consultations.length;
const consultationEvents = consultations.reduce((sum,row)=>sum+Number(row['Consultas CPF']||1),0);
const additionalRepeatEvents = Math.max(0,consultationEvents-distinctCpfCount);
const repeatedGroups = consultations.filter(row=>Number(row['Consultas CPF']||0)>1).length;
const count = status => consultations.filter(row=>row['Status classificado']===status).length;
const dates=consultations.map(row=>row['Timestamp consulta']).filter(Boolean).sort();
const period=dates.length?`${fmtDate(dates[0])} a ${fmtDate(dates[dates.length-1])}`:'Sem consultas';
const processText = row => parseProcesses(row['Processos / valor principal']).map(p=>{
  const parts=[p.numero];
  if (p.data) parts.push(p.data);
  let text=parts.join(' — ');
  if (p.valor_principal_bruto!==null && p.valor_principal_bruto!==undefined && p.valor_principal_bruto!=='') text += ` — Principal: ${fmtMoney(p.valor_principal_bruto)}`;
  return text;
}).join('\n') || '—';
const columns=[
 ['Timestamp consulta','Consulta'],['Número WhatsApp','WhatsApp'],['CPF','CPF'],['Nome TJSP','Nome TJSP'],
 ['Total processos','Qtd. processos'],['Processos / valor principal','Processos / valor principal'],
 ['Status classificado','Status'],['E-mail','E-mail'],['Link gerado em','Link gerado'],
 ['Dias desde consulta','Dias'],['Evidência status','Evidência'],['Consultas CPF','Consultas CPF'],
 ['Primeira consulta CPF','Primeira consulta'],['Última consulta CPF','Última consulta'],['Repetição CPF','Repetição CPF']
];
const statusColor = value=>value==='Pagou'?'#247a3d':value==='Não tinha processos'?'#667085':value.includes('Link gerado')?'#175cd3':value.includes('código pendente')?'#b54708':'#475467';
const tableRows=consultations.map(row=>`<tr>${columns.map(([key])=>{
 let value=row[key];
 if(key==='Processos / valor principal') value=processText(row);
 else if(key.includes('Timestamp')||key.includes('consulta CPF')||key==='Link gerado em') value=fmtDate(value);
 else if(value===null||value===undefined||value==='') value='—';
 const style=key==='Status classificado'?`color:${statusColor(String(value))};font-weight:700;`:'';
 const cellStyle=key==='Processos / valor principal'?'white-space:pre-line;min-width:280px;':'';
 return `<td style="padding:8px;border-bottom:1px solid #e5e7eb;vertical-align:top;${style}${cellStyle}">${esc(value)}</td>`;
}).join('')}</tr>`).join('');
const logoUrl='https://i.imgur.com/hqX2yli.jpeg';
const title='RELATÓRIO SEMANAL ACUMULADO';
const subject=`[TESTE] Relatório semanal acumulado — ${dateFmt.format(generatedAt)}`;
const html=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f3f4f6;font-family:Arial,sans-serif;color:#202124"><div style="max-width:1200px;margin:0 auto;background:#fff;padding:24px"><table role="presentation" style="width:100%;border-bottom:3px solid #004aad;margin-bottom:20px"><tr><td style="width:110px;padding:0 16px 16px 0"><img src="${logoUrl}" alt="Revisa Precatório" style="width:96px;height:auto"></td><td style="padding-bottom:16px"><div style="font-size:22px;font-weight:700;color:#004aad">${title}</div><div style="margin-top:8px;color:#475467">Histórico disponível no banco: ${esc(period)}</div><div style="margin-top:4px;font-size:12px;color:#667085">Emitido em ${esc(dateFmt.format(generatedAt))} (horário de Brasília)</div></td></tr></table><table role="presentation" style="width:100%;border-spacing:8px;margin:0 -8px 12px"><tr><td style="background:#eff6ff;padding:12px">Consultas realizadas<br><strong style="font-size:22px;color:#004aad">${consultationEvents}</strong></td><td style="background:#eff6ff;padding:12px">Consultas únicas (1ª por CPF)<br><strong style="font-size:22px;color:#004aad">${distinctCpfCount}</strong></td><td style="background:#fff7ed;padding:12px">Reconsultas adicionais<br><strong style="font-size:22px;color:#b54708">${additionalRepeatEvents}</strong></td><td style="background:#fff7ed;padding:12px">CPFs com repetição<br><strong style="font-size:22px;color:#b54708">${repeatedGroups}</strong></td><td style="background:#f2f4f7;padding:12px">CPFs sem processos<br><strong style="font-size:22px">${count('Não tinha processos')}</strong></td><td style="background:#effaf3;padding:12px">Pagos<br><strong style="font-size:22px;color:#247a3d">${count('Pagou')}</strong></td></tr></table><div style="font-size:12px;color:#667085;margin:0 0 16px">Consultas realizadas = consultas únicas + reconsultas adicionais. As consultas sem processos também estão incluídas.</div><h2 style="font-size:17px;color:#344054;margin:24px 0 10px">Consultas e processos</h2><div style="font-size:12px;color:#667085;margin:0 0 8px">Uma linha por CPF. Os processos e valores disponíveis aparecem juntos, um processo por linha na mesma célula.</div><div style="overflow-x:auto"><table style="border-collapse:collapse;min-width:1350px;width:100%;font-size:11px;text-align:left"><thead><tr>${columns.map(([,label])=>`<th style="padding:9px;background:#004aad;color:#fff;white-space:nowrap">${esc(label)}</th>`).join('')}</tr></thead><tbody>${tableRows||`<tr><td colspan="${columns.length}" style="padding:16px;text-align:center">Nenhuma consulta encontrada.</td></tr>`}</tbody></table></div><p style="margin:20px 0 0;padding-top:12px;border-top:1px solid #e5e7eb;font-size:11px;color:#667085">Relatório interno. O total inclui consultas sem processos; ausências de evento não comprovam leitura ou desistência. Em CPF consultado por mais de um WhatsApp, a linha usa a consulta mais recente e o snapshot de processos atualmente armazenado.</p></div></body></html>`;
const csvEscape=value=>`"${String(value??'').replace(/"/g,'""')}"`;
const csv='\uFEFF'+[columns.map(([,label])=>csvEscape(label)).join(';'),...consultations.map(row=>columns.map(([key])=>csvEscape(key==='Processos / valor principal'?processText(row):row[key])).join(';'))].join('\r\n');
return [{json:{html,subject},binary:{data:{data:Buffer.from(csv,'utf8').toString('base64'),mimeType:'text/csv',fileName:'revisa-relatorio-acumulado.csv',fileExtension:'csv'}}}];

